import React from 'react';

// Modal component for choosing the orientation
function ChooseOrientationModal({ isOpen, onChoose }) {
  if (!isOpen) return null;

  return (
    <div className="modal-overlay">
      <div className="modal-content">
        <h3>Choose Orientation</h3>
        <p>Please select the orientation for the 8-edge implicant:</p>
        <button onClick={() => onChoose(true)}>Horizontal</button>
        <button onClick={() => onChoose(false)}>Vertical</button>
      </div>
    </div>
  );
}

export default ChooseOrientationModal;